/**
 * Headless Boids simulation on a 200x200 toroidal (wrap-around) space.
 *
 * Three classic Reynolds forces:
 *  - Separation: steer away from nearby flockmates (short-range repulsion).
 *  - Alignment:  steer toward the mean heading of neighbors.
 *  - Cohesion:   steer toward the local center of mass of neighbors.
 *
 * All distances/deltas use minimum-image convention on the torus, so the
 * world wraps in both axes. Updates are synchronous (forces computed from
 * the previous positions/velocities for all agents) and fully deterministic
 * given a seed.
 */

export interface SimConfig {
  seed: number;
  count: number; // number of agents
  size: number; // world is size x size, toroidal
  neighborRadius: number;
  dt: number; // fixed timestep
  ticks: number;
  wSep: number;
  wAlign: number;
  wCoh: number;
  maxSpeed: number;
  minSpeed: number;
  maxForce: number; // clamp on total steering acceleration per tick
  cohesionEnabled: boolean;
}

export const DEFAULT_CONFIG: Omit<SimConfig, "seed"> = {
  count: 60,
  size: 200,
  neighborRadius: 25,
  dt: 0.5,
  ticks: 500,
  wSep: 2.2,
  wAlign: 1.0,
  wCoh: 0.9,
  maxSpeed: 4.0,
  minSpeed: 1.5,
  maxForce: 0.35,
  cohesionEnabled: true,
};

export interface RunResult {
  config: SimConfig;
  /** Flattened positions: [(tick * count + i) * 2] = x/y of agent i at tick. */
  trajectory: Float64Array;
  /** FNV-1a hash over the full quantized trajectory. */
  trajectoryHash: string;
}

/** Small deterministic PRNG (mulberry32). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Minimum-image delta on a torus of given size: result in [-size/2, size/2]. */
export function wrapDelta(d: number, size: number): number {
  let x = d % size;
  if (x < 0) x += size;
  if (x > size / 2) x -= size;
  return x;
}

export function wrapPos(p: number, size: number): number {
  let x = p % size;
  if (x < 0) x += size;
  return x;
}

function hypot(x: number, y: number): number {
  return Math.sqrt(x * x + y * y);
}

/** Seeded spawn: uniform random positions, uniform random headings at cruise speed. */
function spawn(cfg: SimConfig): { xs: Float64Array; ys: Float64Array; vxs: Float64Array; vys: Float64Array } {
  const rand = mulberry32(cfg.seed);
  const n = cfg.count;
  const xs = new Float64Array(n);
  const ys = new Float64Array(n);
  const vxs = new Float64Array(n);
  const vys = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    xs[i] = rand() * cfg.size;
    ys[i] = rand() * cfg.size;
    const angle = rand() * Math.PI * 2;
    const speed = cfg.minSpeed + rand() * (cfg.maxSpeed - cfg.minSpeed);
    vxs[i] = Math.cos(angle) * speed;
    vys[i] = Math.sin(angle) * speed;
  }
  return { xs, ys, vxs, vys };
}

function limit(x: number, y: number, max: number): [number, number] {
  const m = hypot(x, y);
  if (m > max && m > 0) return [(x / m) * max, (y / m) * max];
  return [x, y];
}

class TrajectoryHasher {
  private h = 0x811c9dc5;
  private prev = 0;
  /** FNV-1a over values quantized to 1e-3, order-dependent. */
  update(v: number): void {
    // Quantize to 3 decimals to be robust to float noise while still exact
    // for identical runs.
    let q = Math.round(v * 1000) | 0;
    // Mix in tick boundaries implicitly via value sequence; fold bytes.
    this.h ^= q & 0xff;
    this.h = Math.imul(this.h, 16777619);
    this.h ^= (q >>> 8) & 0xff;
    this.h = Math.imul(this.h, 16777619);
    this.h ^= (q >>> 16) & 0xff;
    this.h = Math.imul(this.h, 16777619);
    this.prev = q;
  }
  hex(): string {
    return (this.h >>> 0).toString(16).padStart(8, "0");
  }
}

/** Advance the simulation `cfg.ticks` fixed-dt steps, recording every tick. */
export function simulate(config: SimConfig): RunResult {
  const cfg = config;
  const n = cfg.count;
  const { xs, ys, vxs, vys } = spawn(cfg);

  const traj = new Float64Array((cfg.ticks + 1) * n * 2);
  const hasher = new TrajectoryHasher();

  const record = (tick: number) => {
    for (let i = 0; i < n; i++) {
      traj[(tick * n + i) * 2] = xs[i];
      traj[(tick * n + i) * 2 + 1] = ys[i];
      hasher.update(xs[i]);
      hasher.update(ys[i]);
    }
  };

  record(0);

  const r2 = cfg.neighborRadius * cfg.neighborRadius;

  for (let tick = 1; tick <= cfg.ticks; tick++) {
    const ax = new Float64Array(n);
    const ay = new Float64Array(n);

    // Compute forces synchronously from current state.
    for (let i = 0; i < n; i++) {
      let sepX = 0,
        sepY = 0;
      let aliX = 0,
        aliY = 0;
      let cohX = 0,
        cohY = 0;
      let neighbors = 0;

      for (let j = 0; j < n; j++) {
        if (j === i) continue;
        const dx = wrapDelta(xs[j] - xs[i], cfg.size);
        const dy = wrapDelta(ys[j] - ys[i], cfg.size);
        const d2 = dx * dx + dy * dy;
        if (d2 > r2 || d2 === 0) continue;
        const d = Math.sqrt(d2);
        neighbors++;

        // Separation: inverse-distance-weighted push away.
        sepX -= dx / d2;
        sepY -= dy / d2;

        // Alignment & cohesion accumulate raw sums.
        aliX += vxs[j];
        aliY += vys[j];
        cohX += dx;
        cohY += dy;
      }

      if (neighbors > 0) {
        // Normalize each steering component to unit magnitude, then weight,
        // so no force dominates merely by having more terms.
        let sx = sepX,
          sy = sepY;
        let m = hypot(sx, sy);
        if (m > 0) {
          sx /= m;
          sy /= m;
        }
        let lx = aliX / neighbors - vxs[i],
          ly = aliY / neighbors - vys[i];
        m = hypot(lx, ly);
        if (m > 0) {
          lx /= m;
          ly /= m;
        }
        let cx = 0,
          cy = 0;
        if (cfg.cohesionEnabled) {
          cx = cohX / neighbors;
          cy = cohY / neighbors;
          m = hypot(cx, cy);
          if (m > 0) {
            cx /= m;
            cy /= m;
          }
        }
        ax[i] = sx * cfg.wSep + lx * cfg.wAlign + cx * cfg.wCoh;
        ay[i] = sy * cfg.wSep + ly * cfg.wAlign + cy * cfg.wCoh;
        [ax[i], ay[i]] = limit(ax[i], ay[i], cfg.maxForce);
      }
    }

    // Integrate with fixed dt, clamp speed, wrap positions.
    for (let i = 0; i < n; i++) {
      vxs[i] += ax[i] * cfg.dt;
      vys[i] += ay[i] * cfg.dt;
      const sp = hypot(vxs[i], vys[i]);
      if (sp > cfg.maxSpeed) {
        vxs[i] = (vxs[i] / sp) * cfg.maxSpeed;
        vys[i] = (vys[i] / sp) * cfg.maxSpeed;
      } else if (sp < cfg.minSpeed && sp > 0) {
        vxs[i] = (vxs[i] / sp) * cfg.minSpeed;
        vys[i] = (vys[i] / sp) * cfg.minSpeed;
      }
      xs[i] = wrapPos(xs[i] + vxs[i] * cfg.dt, cfg.size);
      ys[i] = wrapPos(ys[i] + vys[i] * cfg.dt, cfg.size);
    }

    record(tick);
  }

  return { config: cfg, trajectory: traj, trajectoryHash: hasher.hex() };
}

// ---------------------------------------------------------------------------
// Statistics helpers operating on a recorded trajectory.
// ---------------------------------------------------------------------------

/** Wrapped distance between agents i and j at a given tick. */
export function pairDistance(res: RunResult, tick: number, i: number, j: number): number {
  const n = res.config.count;
  const dx = wrapDelta(res.trajectory[(tick * n + j) * 2] - res.trajectory[(tick * n + i) * 2], res.config.size);
  const dy = wrapDelta(
    res.trajectory[(tick * n + j) * 2 + 1] - res.trajectory[(tick * n + i) * 2 + 1],
    res.config.size,
  );
  return hypot(dx, dy);
}

/** Mean pairwise distance across all C(n,2) unordered pairs at a tick. */
export function meanPairwiseDistance(res: RunResult, tick: number): number {
  const n = res.config.count;
  let sum = 0;
  let pairs = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      sum += pairDistance(res, tick, i, j);
      pairs++;
    }
  }
  return sum / pairs;
}

/** Minimum pairwise distance at a tick. */
export function minPairwiseDistance(res: RunResult, tick: number): number {
  const n = res.config.count;
  let best = Infinity;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const d = pairDistance(res, tick, i, j);
      if (d < best) best = d;
    }
  }
  return best;
}

/** Minimum pairwise distance over every tick of the run. */
export function minPairwiseDistanceOverTime(res: RunResult): number {
  let best = Infinity;
  for (let t = 0; t <= res.config.ticks; t++) {
    const d = minPairwiseDistance(res, t);
    if (d < best) best = d;
  }
  return best;
}

/**
 * Radius of the smallest circle centered on the toroidal mean position that
 * contains every agent (max distance from centroid), using wrapped deltas.
 */
export function boundingCircleRadius(res: RunResult, tick: number): number {
  const n = res.config.count;
  const size = res.config.size;
  // Circular mean for x and y handles clusters straddling the seam.
  let sx = 0,
    sy = 0,
    cx = 0,
    cy = 0;
  for (let i = 0; i < n; i++) {
    const x = res.trajectory[(tick * n + i) * 2];
    const y = res.trajectory[(tick * n + i) * 2 + 1];
    sx += Math.cos((2 * Math.PI * x) / size);
    sy += Math.sin((2 * Math.PI * x) / size);
    cx += Math.cos((2 * Math.PI * y) / size);
    cy += Math.sin((2 * Math.PI * y) / size);
  }
  const mx = (Math.atan2(sy, sx) / (2 * Math.PI)) * size;
  const my = (Math.atan2(cy, cx) / (2 * Math.PI)) * size;
  let r = 0;
  for (let i = 0; i < n; i++) {
    const dx = wrapDelta(res.trajectory[(tick * n + i) * 2] - mx, size);
    const dy = wrapDelta(res.trajectory[(tick * n + i) * 2 + 1] - my, size);
    const d = hypot(dx, dy);
    if (d > r) r = d;
  }
  return r;
}

