import { DEFAULT_CONFIG, simulate, meanPairwiseDistance, minPairwiseDistanceOverTime, boundingCircleRadius } from "./boids.js";

function check(cfg: any) {
  let minD = Infinity, rOn = 0, rOff = 0, m500 = 0;
  for (let seed = 1; seed <= 5; seed++) {
    const on = simulate({ ...DEFAULT_CONFIG, ...cfg, seed });
    const off = simulate({ ...DEFAULT_CONFIG, ...cfg, seed, cohesionEnabled: false });
    if (!(meanPairwiseDistance(on, 500) < meanPairwiseDistance(on, 0))) return null;
    const md = minPairwiseDistanceOverTime(on);
    if (!(md > 1.0)) return null;
    const ro = boundingCircleRadius(off, 500), ri = boundingCircleRadius(on, 500);
    if (!(ro > ri)) return null;
    minD = Math.min(minD, md); rOn += ri; rOff += ro; m500 += meanPairwiseDistance(on, 500);
  }
  return { minD: +minD.toFixed(2), rOn: +(rOn/5).toFixed(0), rOff: +(rOff/5).toFixed(0), m500: +(m500/5).toFixed(1) };
}

