import { describe, expect, it } from "vitest";
import {
  DEFAULT_CONFIG,
  simulate,
  meanPairwiseDistance,
  minPairwiseDistanceOverTime,
  boundingCircleRadius,
  type SimConfig,
} from "../src/boids.js";

const SEEDS = [1, 2, 3, 4, 5];

function makeConfig(seed: number, overrides: Partial<SimConfig> = {}): SimConfig {
  return { ...DEFAULT_CONFIG, seed, ...overrides };
}

describe("boids flocking (60 agents, 200x200 torus, radius 25, fixed dt)", () => {
  it("cohesion+alignment tighten the flock: mean pairwise distance drops after 500 ticks", () => {
    for (const seed of SEEDS) {
      const run = simulate(makeConfig(seed));
      const m0 = meanPairwiseDistance(run, 0);
      const m500 = meanPairwiseDistance(run, 500);
      expect(m500, `seed ${seed}: m0=${m0.toFixed(2)} m500=${m500.toFixed(2)}`).toBeLessThan(m0);
    }
  });

  it("separation holds: minimum pairwise distance stays above 1.0 throughout", () => {
    for (const seed of SEEDS) {
      const run = simulate(makeConfig(seed));
      const minD = minPairwiseDistanceOverTime(run);
      expect(minD, `seed ${seed}: minD=${minD.toFixed(3)}`).toBeGreaterThan(1.0);
    }
  });

  it("cohesion matters: without it the bounding-circle radius at tick 500 is larger", () => {
    for (const seed of SEEDS) {
      const withCohesion = simulate(makeConfig(seed));
      const withoutCohesion = simulate(makeConfig(seed, { cohesionEnabled: false }));
      const rOn = boundingCircleRadius(withCohesion, 500);
      const rOff = boundingCircleRadius(withoutCohesion, 500);
      expect(rOff, `seed ${seed}: rOn=${rOn.toFixed(1)} rOff=${rOff.toFixed(1)}`).toBeGreaterThan(rOn);
    }
  });

  it("is deterministic per seed: identical seeds reproduce the trajectory hash exactly", () => {
    for (const seed of SEEDS) {
      const a = simulate(makeConfig(seed));
      const b = simulate(makeConfig(seed));
      expect(a.trajectoryHash).toBe(b.trajectoryHash);
    }
  });

  it("different seeds produce different trajectories", () => {
    const hashes = new Set<string>();
    for (const seed of SEEDS) {
      hashes.add(simulate(makeConfig(seed)).trajectoryHash);
    }
    expect(hashes.size).toBe(SEEDS.length);
  });
});

